// Simple application with security best practices
// Environment variables loaded from .env file (not committed to repo)

const express = require('express');
const app = express();

// Configuration from environment variables
const PORT = process.env.PORT || 3000;
const NODE_ENV = process.env.NODE_ENV || 'development';
const USE_MOCK_DATA = process.env.USE_MOCK_DATA === 'true';

// Mock data for development/testing (should be in database in production)
const getMockUsers = () => {
  if (!USE_MOCK_DATA) {
    return [];
  }
  return [
    { id: 1, name: 'Alice', email: 'alice@example.com' },
    { id: 2, name: 'Bob', email: 'bob@example.com' },
  ];
};

// Health check endpoint
app.get('/health', (req, res) => {
  res.json({ 
    status: 'ok', 
    timestamp: new Date().toISOString(),
    environment: NODE_ENV 
  });
});

// Users endpoint - in production should use database
app.get('/users', (req, res) => {
  // TODO: Add authentication middleware
  // TODO: Replace with database query in production
  const users = getMockUsers();
  res.json(users);
});

// Start server
const server = app.listen(PORT, () => {
  console.log(`Server running on port ${PORT} in ${NODE_ENV} mode`);
  if (USE_MOCK_DATA) {
    console.log('⚠️  Using mock data - not for production!');
  }
});

// Graceful shutdown
process.on('SIGTERM', () => {
  console.log('SIGTERM signal received: closing HTTP server');
  server.close(() => {
    console.log('HTTP server closed');
  });
});

module.exports = app;

/**
 * Centralized configuration management
 * All environment variables and configuration should be accessed through this module
 */

// Load environment variables from .env file (for local development)
// In production, use proper secrets management (AWS Secrets Manager, etc.)
require('dotenv').config();

const config = {
  // Application
  nodeEnv: process.env.NODE_ENV || 'development',
  port: parseInt(process.env.PORT || '3000', 10),

  // Feature flags
  useMockData: process.env.USE_MOCK_DATA === 'true',

  // Security
  allowedOrigins: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  rateLimitWindowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS || '900000', 10), // 15 min
  rateLimitMaxRequests: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS || '100', 10),

  // Database (if needed)
  databaseUrl: process.env.DATABASE_URL,

  // External Services (if needed)
  aws: {
    accessKeyId: process.env.AWS_ACCESS_KEY_ID,
    secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    region: process.env.AWS_REGION || 'us-east-1',
  },

  // API Keys (if needed)
  apiKeys: {
    anthropic: process.env.ANTHROPIC_API_KEY,
    stripe: process.env.STRIPE_SECRET_KEY,
  },

  // Logging
  logfireToken: process.env.LOGFIRE_TOKEN,
};

// Validation: Ensure required variables are set in production
if (config.nodeEnv === 'production') {
  const requiredVars = [
    // Add required variables for production here
    // 'DATABASE_URL',
    // 'STRIPE_SECRET_KEY',
  ];

  const missing = requiredVars.filter(varName => !process.env[varName]);

  if (missing.length > 0) {
    console.error('❌ Missing required environment variables in production:');
    missing.forEach(varName => console.error(`  - ${varName}`));
    process.exit(1);
  }
}

// Redact sensitive values in logs
config.toSafeString = function() {
  return JSON.stringify({
    ...config,
    databaseUrl: config.databaseUrl ? '***REDACTED***' : undefined,
    aws: {
      ...config.aws,
      accessKeyId: config.aws.accessKeyId ? '***REDACTED***' : undefined,
      secretAccessKey: config.aws.secretAccessKey ? '***REDACTED***' : undefined,
    },
    apiKeys: {
      anthropic: config.apiKeys.anthropic ? '***REDACTED***' : undefined,
      stripe: config.apiKeys.stripe ? '***REDACTED***' : undefined,
    },
    logfireToken: config.logfireToken ? '***REDACTED***' : undefined,
  }, null, 2);
};

module.exports = config;

